#!/usr/bin/env python3
"""Copy the small facts this repo needs out of the pinned upstream checkouts into tracked files.

    python third_party/extract_assets.py

Writes (all generated; do not edit by hand, re-run this script instead):
  src/utils/datasets/class_lists/imagenet_1k_wnids.txt   1000 wnids in torchvision class order
  src/utils/datasets/class_lists/imagenet_r_wnids.txt    200 ImageNet-R wnids
  src/utils/datasets/class_lists/imagenet_a_wnids.txt    200 ImageNet-A wnids
  cfgs/protocols.yaml                                     CoTTA's 10 corruption orders + CCC settings

Every value is parsed from the upstream source with `ast.literal_eval` (never exec'd).
"""

from __future__ import annotations

import ast
from pathlib import Path

import yaml

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent

# generate.py abbreviates two corruption names; everything else here uses ImageNet-C's.
_CCC_NAME = {"elastic": "elastic_transform", "jpeg": "jpeg_compression"}


def _assigned_literals(path: Path, name: str) -> list:
    """Every literal assigned to a variable called `name` in `path`, in source order."""
    out = []
    for node in ast.walk(ast.parse(path.read_text())):
        if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == name for t in node.targets):
            try:
                out.append(ast.literal_eval(node.value))
            except ValueError:
                pass  # not a pure literal (e.g. a list comprehension)
    return out


def class_lists() -> None:
    r_eval = HERE / "imagenet-r" / "eval.py"
    a_eval = HERE / "natural-adv-examples" / "eval.py"
    (all_wnids,) = _assigned_literals(r_eval, "all_wnids")
    (r_wnids,) = _assigned_literals(r_eval, "imagenet_r_wnids")
    (thousand_k_to_200,) = _assigned_literals(a_eval, "thousand_k_to_200")

    assert len(all_wnids) == 1000 and all_wnids == sorted(all_wnids), "1k wnids must be the sorted torchvision order"
    assert len(r_wnids) == 200 and set(r_wnids) <= set(all_wnids)
    a_idx = [k for k, v in thousand_k_to_200.items() if v != -1]
    assert len(a_idx) == 200 and sorted(thousand_k_to_200[k] for k in a_idx) == list(range(200))
    # ImageNet-A's own mapping is 1k-index -> 0..199 in ascending 1k order, i.e. the same as sorted wnids.
    assert [thousand_k_to_200[k] for k in a_idx] == list(range(200))
    a_wnids = [all_wnids[k] for k in a_idx]

    out = ROOT / "src" / "utils" / "datasets" / "class_lists"
    out.mkdir(parents=True, exist_ok=True)
    (out / "imagenet_1k_wnids.txt").write_text("\n".join(all_wnids) + "\n")
    (out / "imagenet_r_wnids.txt").write_text("\n".join(w for w in all_wnids if w in set(r_wnids)) + "\n")
    (out / "imagenet_a_wnids.txt").write_text("\n".join(a_wnids) + "\n")
    print(f"class lists -> {out.relative_to(ROOT)} (1k=1000, R=200, A=200)")


def protocols() -> None:
    orders = []
    for i in range(10):
        cfg = yaml.safe_load((HERE / "cotta" / "imagenet" / "cfgs" / "10orders" / "tent" / f"tent{i}.yaml").read_text())
        orders.append(cfg["CORRUPTION"]["TYPE"])
    assert all(len(o) == 15 and sorted(o) == sorted(orders[0]) for o in orders)
    assert len({tuple(o) for o in orders}) == 10

    ccc_py = HERE / "CCC" / "generate.py"
    easy, medium, hard = _assigned_literals(ccc_py, "noises")  # source order: baseline>=40, >=20, else
    (speeds,) = _assigned_literals(HERE / "CCC" / "ccc_config.py", "SPEEDS")
    (seeds,) = _assigned_literals(HERE / "CCC" / "ccc_config.py", "SEEDS")
    ccc_cfg = {
        "speeds": list(speeds),
        "seeds": list(seeds),
        "images_per_stream": 7_500_000,
        "images_per_shard": 25_000,
        # --baseline passed to generate.py; "baseline accuracy" of the stream
        "baseline": {"easy": 40, "medium": 20, "hard": 0},
        "corruptions": {
            name: [_CCC_NAME.get(c, c) for c in lst]
            for name, lst in (("easy", easy), ("medium", medium), ("hard", hard))
        },
    }
    doc = {"cotta_orders": orders, "ccc": ccc_cfg}
    header = (
        "# GENERATED by third_party/extract_assets.py -- do not edit by hand.\n"
        "# cotta_orders: cotta/imagenet/cfgs/10orders/tent/tent{0..9}.yaml @ c212a20 (identical to the cifar ones).\n"
        "# ccc: CCC/ccc_config.py and the three `noises = [...]` lists in CCC/generate.py @ c47aff6.\n"
    )
    path = ROOT / "cfgs" / "protocols.yaml"
    path.write_text(header + yaml.safe_dump(doc, sort_keys=False, default_flow_style=None, width=100))
    print(f"protocols -> {path.relative_to(ROOT)} (10 orders; CCC easy/medium/hard = "
          f"{len(easy)}/{len(medium)}/{len(hard)} corruptions)")


if __name__ == "__main__":
    class_lists()
    protocols()
